// Объявляем проверку: сервер должен вернуть HTTP-статус 200.
pm.test("HTTP-статус — 200", function () {
    pm.response.to.have.status(200);
});

// Проверяем содержимое ответа, а не только успешный HTTP-статус.
pm.test("Приложение сообщает status: OK", function () {
    // Разбираем JSON ответа и сохраняем его в переменную body.
    const body = pm.response.json();

    // Проверка пройдёт, только если поле status равно строке "OK".
    pm.expect(body.status).to.equal("OK");
});

// Генерируем уникальный адрес перед отправкой запроса.
const email = "postman." + pm.variables.replaceIn("{{$guid}}") + "@example.com";

// Сохраняем email в коллекции: он понадобится для последующих проверок.
pm.collectionVariables.set("test_email", email);

// Убираем старый ID, чтобы при ошибке создания не использовать прежнюю карточку.
pm.collectionVariables.unset("user_id");

// Проверяем, что сервер подтвердил создание пользователя.
pm.test("Пользователь создан — 201", function () {
    pm.response.to.have.status(201);
});

// Проверяем карточку и запоминаем её ID только при успешном создании.
if (pm.response.code === 201) {
    const user = pm.response.json();

    pm.test("Ответ содержит положительный целочисленный ID", function () {
        pm.expect(user.id).to.be.a("number");
        pm.expect(Number.isInteger(user.id)).to.equal(true);
        pm.expect(user.id).to.be.above(0);
    });

    pm.test("Имя и email совпадают с отправленными", function () {
        pm.expect(user.name).to.equal("Postman Test");
        pm.expect(user.email).to.equal(
            pm.collectionVariables.get("test_email")
        );
    });

    // Запоминаем номер карточки для GET, PATCH и DELETE.
    pm.collectionVariables.set("user_id", user.id);
}

// Проверяем, что сервер нашёл пользователя.
pm.test("Пользователь найден — 200", function () {
    pm.response.to.have.status(200);
});

// Проверяем данные только при успешном ответе.
if (pm.response.code === 200) {
    // Разбираем JSON с карточкой, прочитанной из базы.
    const user = pm.response.json();

    // Переменная может храниться как строка, поэтому приводим ID к числу.
    const expectedId = Number(pm.collectionVariables.get("user_id"));

    pm.test("Получен пользователь с нужным ID", function () {
        pm.expect(user.id).to.equal(expectedId);
    });

    pm.test("Имя и email сохранились правильно", function () {
        pm.expect(user.name).to.equal("Postman Test");
        pm.expect(user.email).to.equal(
            pm.collectionVariables.get("test_email")
        );
    });
}

// Проверяем, что сервер успешно выполнил обновление.
pm.test("Пользователь обновлён — 200", function () {
    pm.response.to.have.status(200);
});

// При успешном ответе разбираем обновлённую карточку.
if (pm.response.code === 200) {
    const user = pm.response.json();

    // Читаем ID созданного пользователя и приводим его к числу.
    const expectedId = Number(pm.collectionVariables.get("user_id"));

    pm.test("ID пользователя не изменился", function () {
        pm.expect(user.id).to.equal(expectedId);
    });

    pm.test("Имя изменилось, email сохранился", function () {
        pm.expect(user.name).to.equal("Postman Updated");
        pm.expect(user.email).to.equal(
            pm.collectionVariables.get("test_email")
        );
    });
}

// Проверяем, что сервер нашёл пользователя.
pm.test("Пользователь найден — 200", function () {
    pm.response.to.have.status(200);
});

// Проверяем данные только при успешном ответе.
if (pm.response.code === 200) {
    // Разбираем JSON с карточкой, прочитанной из базы.
    const user = pm.response.json();

    // Переменная может храниться как строка, поэтому приводим ID к числу.
    const expectedId = Number(pm.collectionVariables.get("user_id"));

    pm.test("Получен пользователь с нужным ID", function () {
        pm.expect(user.id).to.equal(expectedId);
    });

    pm.test("Имя и email сохранились правильно", function () {
        // Проверяем, что новое имя сохранилось и читается отдельным запросом.
        pm.expect(user.name).to.equal("Postman Updated");
        pm.expect(user.email).to.equal(
            pm.collectionVariables.get("test_email")
        );
    });
}

// Проверяем, что сервер подтвердил удаление.
pm.test("Пользователь удалён — 204", function () {
    pm.response.to.have.status(204);
});

// Ответ 204 не должен содержать тело.
pm.test("Тело ответа пустое", function () {
    pm.expect(pm.response.text()).to.equal("");
});

// Проверяем, что удалённая карточка больше не находится.
pm.test("Пользователь отсутствует — 404", function () {
    pm.response.to.have.status(404);
});

// Проверяем сообщение; trim убирает перевод строки в конце ответа.
pm.test("Сервер сообщил, что пользователь не найден", function () {
    pm.expect(pm.response.text().trim()).to.equal(
        "Пользователь не найден"
    );
});
